import React from 'react';

function Home(){

  const products = [
    {
      _id: 1,
      name: "Nike Shoes",
      price: 2999
    },
    {
      _id: 2,
      name: "T-Shirt",
      price: 999
    },
    {
      _id: 3,
      name: "Headphones",
      price: 1999
    }
  ];

  return (
    <div style={{padding:"20px"}}>
      <h1>ShopEasy</h1>

      {products.map((p)=>(
        <div
          key={p._id}
          style={{
            border:"1px solid gray",
            padding:"10px",
            margin:"10px",
            width:"200px"
          }}
        >
          <h3>{p.name}</h3>
          <p>₹{p.price}</p>
          <button>Add to Cart</button>
        </div>
      ))}
    </div>
  );
}

export default Home;
